terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where the Lex V2 bot will be created."
  type        = string
  default     = "us-east-1"
}

variable "bot_name" {
  description = "Name of the Amazon Lex V2 bot."
  type        = string
  default     = "example-lexv2-bot"
}

